"""
blockchain_service.py
Handles all interactions with the DocumentVerifier smart contract via Web3.py.
"""

import os
import json
from pathlib import Path

from web3 import Web3
from web3.exceptions import ContractLogicError
from dotenv import load_dotenv

load_dotenv()

# ── Configuration ─────────────────────────────────────────────────────────────

RPC_URL           = os.getenv("RPC_URL", "http://127.0.0.1:8545")
CONTRACT_ADDRESS  = os.getenv("CONTRACT_ADDRESS", "")
PRIVATE_KEY       = os.getenv("PRIVATE_KEY", "")

# ABI file is generated by the deploy script (blockchain/scripts/deploy.js)
ABI_PATH = Path(__file__).parent.parent / "abi" / "DocumentVerifier.json"


# ── Web3 connection ───────────────────────────────────────────────────────────

def _get_web3() -> Web3:
    """Return a connected Web3 instance."""
    w3 = Web3(Web3.HTTPProvider(RPC_URL))
    if not w3.is_connected():
        raise ConnectionError(
            f"Cannot connect to blockchain node at {RPC_URL}. "
            "Make sure 'npx hardhat node' is running."
        )
    return w3


def _get_contract(w3: Web3):
    """Load and return the deployed contract instance."""
    if not CONTRACT_ADDRESS:
        raise ValueError(
            "CONTRACT_ADDRESS is not set. Deploy the contract first and add "
            "the address to backend/.env."
        )

    if not ABI_PATH.exists():
        raise FileNotFoundError(
            f"ABI file not found at {ABI_PATH}. "
            "Run 'npx hardhat run scripts/deploy.js' to generate it."
        )

    with open(ABI_PATH) as f:
        abi_data = json.load(f)

    abi = abi_data.get("abi", abi_data)  # handle both {abi:[...]} and [...]

    checksum_address = Web3.to_checksum_address(CONTRACT_ADDRESS)
    return w3.eth.contract(address=checksum_address, abi=abi)


def _get_account(w3: Web3):
    """Return the account derived from PRIVATE_KEY."""
    if not PRIVATE_KEY:
        raise ValueError(
            "PRIVATE_KEY is not set. Add a test wallet private key to backend/.env."
        )
    return w3.eth.account.from_key(PRIVATE_KEY)


def _send_transaction(w3: Web3, contract_function):
    """
    Sign and send a state-changing transaction.

    Args:
        w3:                Web3 instance.
        contract_function: A prepared contract function call
                           (e.g. contract.functions.registerDocument(...)).

    Returns:
        The transaction receipt.
    """
    account = _get_account(w3)

    tx = contract_function.build_transaction({
        "from":  account.address,
        "nonce": w3.eth.get_transaction_count(account.address),
        "gas":   300_000,
        "gasPrice": w3.eth.gas_price,
    })

    signed_tx = w3.eth.account.sign_transaction(tx, private_key=PRIVATE_KEY)
    # Web3.py <6 uses `rawTransaction`; >=6 uses `raw_transaction` — support both
    raw_tx    = getattr(signed_tx, "raw_transaction", None) or signed_tx.rawTransaction
    tx_hash   = w3.eth.send_raw_transaction(raw_tx)
    receipt   = w3.eth.wait_for_transaction_receipt(tx_hash, timeout=120)

    return receipt


# ── Public API ────────────────────────────────────────────────────────────────

def register_document(document_id: str, cid: str) -> dict:
    """
    Call registerDocument() on the smart contract.

    Returns:
        dict with tx_hash and issuer address.

    Raises:
        RuntimeError on contract revert.
    """
    w3       = _get_web3()
    contract = _get_contract(w3)
    account  = _get_account(w3)

    try:
        fn      = contract.functions.registerDocument(document_id, cid)
        receipt = _send_transaction(w3, fn)
    except ContractLogicError as e:
        raise RuntimeError(f"Contract revert: {e}") from e

    return {
        "tx_hash": receipt.transactionHash.hex(),
        "issuer":  account.address,
        "status":  "success" if receipt.status == 1 else "failed",
    }


def verify_document(document_id: str, cid: str) -> bool:
    """
    Call verifyDocument() on the smart contract (read-only).

    Returns:
        True if the CID matches and the document is valid, False otherwise.

    Raises:
        RuntimeError if the document does not exist (contract reverts).
    """
    w3       = _get_web3()
    contract = _get_contract(w3)

    try:
        return contract.functions.verifyDocument(document_id, cid).call()
    except ContractLogicError as e:
        raise RuntimeError(f"Contract revert: {e}") from e


def get_document(document_id: str) -> dict:
    """
    Call getDocument() on the smart contract (read-only).

    Returns:
        dict with documentId, cid, issuer, timestamp, valid.

    Raises:
        RuntimeError if the document is not found.
    """
    w3       = _get_web3()
    contract = _get_contract(w3)

    try:
        doc_id, cid, issuer, timestamp, valid = (
            contract.functions.getDocument(document_id).call()
        )
    except ContractLogicError as e:
        raise RuntimeError(f"Contract revert: {e}") from e

    return {
        "documentId": doc_id,
        "cid":        cid,
        "issuer":     issuer,
        "timestamp":  timestamp,
        "valid":      valid,
    }


def revoke_document(document_id: str) -> dict:
    """
    Call revokeDocument() on the smart contract.

    Returns:
        dict with tx_hash.

    Raises:
        RuntimeError on contract revert.
    """
    w3       = _get_web3()
    contract = _get_contract(w3)

    try:
        fn      = contract.functions.revokeDocument(document_id)
        receipt = _send_transaction(w3, fn)
    except ContractLogicError as e:
        raise RuntimeError(f"Contract revert: {e}") from e

    return {
        "tx_hash": receipt.transactionHash.hex(),
        "status":  "success" if receipt.status == 1 else "failed",
    }


# ── Transaction Verification (for MetaMask-based registration) ──────────────────

def verify_registration_transaction(
    tx_hash: str,
    expected_doc_hash: str,
    expected_cid: str,
    expected_signer: str,
) -> dict:
    """
    Independently verify a blockchain transaction that an organization claims
    registered their document.

    Checks:
      1. Transaction exists and receipt status == 1 (success)
      2. Transaction was sent TO the contract address
      3. The transaction input decodes to registerDocument(documentId, cid)
      4. documentId == expected_doc_hash and cid == expected_cid
      5. The transaction sender (from) == expected_signer (the org's wallet)

    Args:
        tx_hash:         The transaction hash (hex string)
        expected_doc_hash: The SHA-256 hash we expect as documentId on-chain
        expected_cid:    The IPFS CID we expect on-chain
        expected_signer: The wallet address we expect as the sender

    Returns:
        dict with verified=True/False, plus details on success.

    Raises:
        RuntimeError if the blockchain node is unreachable.
    """
    w3       = _get_web3()
    contract = _get_contract(w3)

    # ── Normalize inputs ───────────────────────────────────────────────────────
    tx_hash = tx_hash if tx_hash.startswith("0x") else f"0x{tx_hash}"
    expected_signer = Web3.to_checksum_address(expected_signer)

    # ── 1. Fetch the transaction ────────────────────────────────────────────────
    try:
        tx = w3.eth.get_transaction(tx_hash)
    except Exception as e:
        raise RuntimeError(f"Transaction not found: {e}")

    if tx is None:
        raise RuntimeError(f"Transaction {tx_hash} not found on the blockchain.")

    # ── 2. Check receipt status ────────────────────────────────────────────────
    try:
        receipt = w3.eth.get_transaction_receipt(tx_hash)
    except Exception as e:
        raise RuntimeError(f"Transaction receipt not found: {e}")

    if receipt is None:
        raise RuntimeError("Transaction has not been mined yet.")

    if receipt.status != 1:
        return {"verified": False, "reason": "Transaction failed on-chain (status != 1)."}

    # ── 3. Check the transaction was sent to our contract ───────────────────────
    tx_to = tx.get("to")
    if tx_to is None or tx_to.lower() != CONTRACT_ADDRESS.lower():
        return {
            "verified": False,
            "reason": f"Transaction was not sent to the DocumentVerifier contract (sent to {tx_to}).",
        }

    # ── 4. Decode the input and verify the function + args ─────────────────────
    try:
        func_obj, params = contract.decode_function_input(tx["input"])
    except Exception:
        return {"verified": False, "reason": "Could not decode transaction input — not a valid contract call."}

    func_name = getattr(func_obj, "fn_name", None) or str(func_obj)
    if "registerDocument" not in func_name:
        return {"verified": False, "reason": f"Transaction called '{func_name}', not registerDocument."}

    on_chain_doc_id = params.get("documentId", params.get("document_id", ""))
    on_chain_cid    = params.get("cid", "")

    if on_chain_doc_id != expected_doc_hash:
        return {
            "verified": False,
            "reason": f"documentId mismatch: expected {expected_doc_hash}, got {on_chain_doc_id}.",
        }

    if on_chain_cid != expected_cid:
        return {
            "verified": False,
            "reason": f"CID mismatch: expected {expected_cid}, got {on_chain_cid}.",
        }

    # ── 5. Verify the sender matches the org's linked wallet ────────────────────
    tx_from = tx.get("from")
    if tx_from is None:
        return {"verified": False, "reason": "Could not determine transaction sender."}

    tx_from = Web3.to_checksum_address(tx_from)
    if tx_from != expected_signer:
        return {
            "verified": False,
            "reason": f"Sender mismatch: expected {expected_signer}, got {tx_from}.",
        }

    # ── All checks passed ──────────────────────────────────────────────────────
    return {
        "verified":   True,
        "tx_hash":     tx_hash,
        "from":        tx_from,
        "to":          tx_to,
        "block_number": receipt.blockNumber,
        "status":       receipt.status,
        "gas_used":     receipt.gasUsed,
    }


# ── Wallet Signature Verification (for wallet linking) ──────────────────────────

def verify_wallet_signature(nonce: int, signature: str, expected_address: str) -> bool:
    """
    Verify that a MetaMask signature was produced by the claimed wallet address.

    The frontend asks the user to sign a message like:
        "Link this wallet to TrueDocs\nNonce: 12345"

    The backend recovers the signer address from the signature and checks it
    matches the expected address.

    Args:
        nonce:           The nonce that was given to the frontend
        signature:       The hex signature from MetaMask personal_sign
        expected_address: The wallet address the frontend claims to own

    Returns:
        True if the signature was produced by expected_address.
    """
    from eth_account import Account
    from eth_account.messages import encode_defunct

    message = f"Link this wallet to TrueDocs\nNonce: {nonce}"
    msg = encode_defunct(text=message)

    try:
        recovered = Account.recover_message(msg, signature=signature)
        return recovered.lower() == expected_address.lower()
    except Exception:
        return False
